    case PROT_WRITE:
        if( hnd = CreateFileMapping( HANDLE( _get_osfhandle( fd ) ), nullptr, PAGE_READWRITE, 0, 0, nullptr ) )
        {
            map = MapViewOfFile( hnd, FILE_MAP_WRITE, 0, 0, length );
            CloseHandle( hnd );
        }
        break;
    }

    return map ? (char*)map + offset : (void*)-1;
}

